//! The design tokens, generated by `build.rs` from `data/design/tokens.json`.

/// The three looks of the app.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Theme {
    Day,
    Dusk,
    Night,
}

pub type Rgba = (f64, f64, f64, f64);

impl Theme {
    fn index(self) -> usize {
        match self {
            Theme::Day => 0,
            Theme::Dusk => 1,
            Theme::Night => 2,
        }
    }
}

/// The colour of `token` in `theme`.
pub fn color(token: Token, theme: Theme) -> Rgba {
    COLOURS[token as usize][theme.index()]
}

/// Millimetres on screen in CSS pixels, which is what the chart tokens in `mm` mean.
pub const MM_PX: f64 = 96.0 / 25.4;

include!(concat!(env!("OUT_DIR"), "/tokens.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn colours_parse_in_every_theme() {
        let (r, g, b, a) = color(Token::OwnShip, Theme::Day);
        assert!(r < 0.1 && g < 0.1 && b < 0.12 && a == 1.0);
        let (.., a) = color(Token::RouteInactive, Theme::Night);
        assert_eq!(a, 0.6);
        let (r, ..) = color(Token::OverlayHalo, Theme::Day);
        assert_eq!(r, 1.0);
    }

    #[test]
    fn numbers_come_with_their_units() {
        assert_eq!(STROKE_HALO, 1.5);
        assert_eq!(SECTOR_RADIUS, 25.0);
        assert_eq!(DANGER_BLINK, 500.0);
        assert_eq!(ALARM_REPEAT, 4000.0);
        assert_eq!(HIT_MIN_UNDERWAY, 44.0);
    }

    #[test]
    fn every_token_has_a_distinct_name() {
        let mut names: Vec<&str> = Token::ALL.iter().map(|t| t.name()).collect();
        names.sort();
        names.dedup();
        assert_eq!(names.len(), TOKEN_COUNT);
        assert_eq!(Token::WindBarb.name(), "wind-barb");
    }
}
